import React, { useState, useRef } from 'react';
import QRCode from 'react-qr-code';
import { saveAs } from 'file-saver'; // You'll need: npm install file-saver

const QRGenerator = () => {
  const [value, setValue] = useState('https://google.com');
  const [fgColor, setFgColor] = useState('#000000');
  const [bgColor, setBgColor] = useState('#ffffff');
  const qrRef = useRef();

  const downloadQR = () => {
    const svg = document.getElementById("QRCode");
    const svgData = new XMLSerializer().serializeToString(svg);
    const canvas = document.createElement("canvas");
    const ctx = canvas.getContext("2d");
    const img = new Image();

    img.onload = () => {
      canvas.width = img.width;
      canvas.height = img.height;
      ctx.drawImage(img, 0, 0);
      const pngFile = canvas.toDataURL("image/png");
      saveAs(pngFile, "qr-code.png");
    };
    img.src = "data:image/svg+xml;base64," + btoa(svgData);
  };

  return (
    <div className="min-h-screen bg-gray-100 flex flex-col items-center justify-center p-6">
      <div className="bg-white p-8 rounded-xl shadow-2xl w-full max-w-md">
        <h1 className="text-2xl font-bold mb-6 text-center text-blue-600">QR Suite Pro</h1>

        <div className="space-y-4">
          <input
            type="text"
            value={value}
            onChange={(e) => setValue(e.target.value)}
            className="w-full p-3 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 outline-none"
            placeholder="Enter URL or text..."
          />

          <div className="flex gap-4">
            <div className="flex-1">
              <label className="text-xs font-semibold uppercase text-gray-500">Foreground</label>
              <input type="color" value={fgColor} onChange={(e) => setFgColor(e.target.value)} className="w-full h-10 rounded-md cursor-pointer" />
            </div>
            <div className="flex-1">
              <label className="text-xs font-semibold uppercase text-gray-500">Background</label>
              <input type="color" value={bgColor} onChange={(e) => setBgColor(e.target.value)} className="w-full h-10 rounded-md cursor-pointer" />
            </div>
          </div>
        </div>

        <div className="mt-8 flex flex-col items-center">
          <div className="p-4 bg-white border rounded-lg shadow-inner">
            <QRCode id="QRCode" value={value} fgColor={fgColor} bgColor={bgColor} size={200} />
          </div>

          <button 
            onClick={downloadQR}
            className="mt-6 w-full bg-blue-600 text-white py-3 rounded-lg font-semibold hover:bg-blue-700 transition"
          >
            Download PNG
          </button>
        </div>
      </div>
    </div>
  );
};

export default QRGenerator;
